"""Statistical test of the keyed delivery holdout (training-use evidence), as needed to VERIFY evidence.

At delivery the time axis is cut into blocks; a key decides which blocks are withheld. A model trained on the delivered
blocks fits them better than the withheld ones. S = mean loss on withheld blocks - mean loss on delivered blocks.
Under H0 ("the model never saw this data") the owner's assignment is one exchangeable draw among decoy assignments, so
the permutation p-value is exact (docs/FORMAL.md, T2; conditional version T3). Reference normalisation and the
fairness check are described in the functions below.
"""
from __future__ import annotations

import functools
import hashlib
import numpy as np
import pandas as pd
from .prf import domain_id, prf_unit


def assign(key: bytes, n_blocks: int, q: float) -> np.ndarray:
    """True = withheld. Exactly round(q * n_blocks) blocks, chosen by a keyed random ranking."""
    u = prf_unit(key, domain_id("holdout"), np.arange(n_blocks))
    k = max(1, int(round(q * n_blocks)))
    w = np.zeros(n_blocks, bool)
    w[np.argsort(u)[:k]] = True
    return w


def delivered_runs(n_rows_total: int, params: dict, key: bytes) -> list[tuple[int, int]]:
    """Contiguous delivered row ranges (consecutive delivered blocks merge)."""
    w = assign(key, params["n_blocks"], params["q"])
    runs, cur = [], None
    for b in range(params["n_blocks"]):
        lo = params["start"] + b * params["block_len"]
        if not w[b]:
            cur = [lo, lo + params["block_len"]] if cur is None else [cur[0], lo + params["block_len"]]
        elif cur is not None:
            runs.append(tuple(cur)); cur = None
    if cur is not None:
        runs.append(tuple(cur))
    return runs


def make_queries(original: pd.DataFrame, params: dict, columns: list[str], context: int, horizon: int,
                 per_block: int = 16, seed: int = 0) -> dict:
    """Black-box query set: `per_block` windows lying fully inside every block, for every channel.
    The owner sends `ctx` to the suspect model and records its forecasts; `fut` stays with the owner."""
    rng = np.random.default_rng(seed)
    bl, st, nb = params["block_len"], params["start"], params["n_blocks"]
    if bl < context + horizon:
        raise ValueError(f"block_len {bl} must be >= context + horizon = {context + horizon}")
    blk, col, start, ctx, fut, scale = [], [], [], [], [], []
    for j, c in enumerate(columns):
        x = original[c].to_numpy(float)
        scale.append(float(np.std(x[st:st + nb * bl])) or 1.0)
        offs = rng.integers(0, bl - context - horizon + 1, size=(nb, per_block))
        starts = (st + np.arange(nb)[:, None] * bl + offs).ravel()
        blk.append(np.repeat(np.arange(nb), per_block)); col.append(np.full(starts.size, j)); start.append(starts)
        ctx.append(np.stack([x[s:s + context] for s in starts]))
        fut.append(np.stack([x[s + context:s + context + horizon] for s in starts]))
    return {"columns": list(columns), "context": context, "horizon": horizon, "per_block": per_block, "seed": seed,
            "block": np.concatenate(blk), "col": np.concatenate(col), "start": np.concatenate(start),
            "ctx": np.concatenate(ctx), "fut": np.concatenate(fut), "scale": np.array(scale)}


def losses_from_predictions(q: dict, pred: np.ndarray, n_blocks: int) -> np.ndarray:
    """Per-block mean squared error (scaled per channel), averaged over channels."""
    err = (((np.asarray(pred, float) - q["fut"]) / q["scale"][q["col"]][:, None]) ** 2).mean(1)
    out = np.zeros(n_blocks)
    for j in range(len(q["columns"])):
        m = q["col"] == j
        out += np.bincount(q["block"][m], weights=err[m], minlength=n_blocks) / np.maximum(
            np.bincount(q["block"][m], minlength=n_blocks), 1)
    return out / len(q["columns"])


def ridge_reference(original: pd.DataFrame, params: dict, q: dict, ridge: float = 1e-3, stride: int = 4) -> np.ndarray:
    """DETERMINISTIC reference for normalisation, recomputable by an arbiter from the original data:
    per channel, a closed-form ridge regression (window-mean removed) fitted on windows from ALL blocks
    (delivered and withheld alike), predicting the query windows. Returns per-block reference losses.
    Unlike a trained network, nobody can steer it towards the withheld blocks."""
    L, H = q["context"], q["horizon"]
    bl, st, nb = params["block_len"], params["start"], params["n_blocks"]
    pred = np.zeros_like(q["fut"])
    for j, c in enumerate(q["columns"]):
        x = original[c].to_numpy(float)[st:st + nb * bl]
        idx = np.arange(0, len(x) - L - H + 1, stride)
        X = np.stack([x[i:i + L] for i in idx]); Y = np.stack([x[i + L:i + L + H] for i in idx])
        mu = X.mean(1, keepdims=True)
        Xc, Yc = X - mu, Y - mu
        W = np.linalg.solve(Xc.T @ Xc + ridge * len(Xc) * np.eye(L), Xc.T @ Yc)
        m = q["col"] == j
        cm = q["ctx"][m].mean(1, keepdims=True)
        pred[m] = (q["ctx"][m] - cm) @ W + cm
    return losses_from_predictions(q, pred, nb)


def decoy_keys_many(n: int, seed: int = 0) -> list[bytes]:
    return [hashlib.sha256(b"provenmark/holdout-decoy" + seed.to_bytes(8, "little") + i.to_bytes(8, "little")).digest()
            for i in range(n)]


@functools.lru_cache(maxsize=32)
def _decoy_assignments_cached(n_decoys: int, seed: int, n_blocks: int, q: float) -> np.ndarray:
    W = np.stack([assign(k, n_blocks, q) for k in decoy_keys_many(n_decoys, seed)])
    W.setflags(write=False)
    return W


def _decoy_assignments(n_decoys, seed, n_blocks, q):
    return _decoy_assignments_cached(int(n_decoys), int(seed), int(n_blocks), float(q))


def holdout_test(losses: np.ndarray, params: dict, real_key: bytes, n_decoys: int = 10000, seed: int = 0,
                 reference: np.ndarray | None = None, mask: np.ndarray | None = None) -> dict:
    """Exact permutation test on precomputed block losses.
    `reference`: per-block losses of a model the OWNER trained on ALL blocks (delivered and withheld alike). It
    measures how hard each block is; the statistic then uses log(loss / reference). The reference does not depend on
    the key's assignment, so exchangeability -- and the exact p-value -- is preserved, while block-difficulty
    variance (e.g. hard weeks vs easy weeks) is removed."""
    if reference is not None:
        losses = np.log(np.maximum(losses, 1e-12)) - np.log(np.maximum(reference, 1e-12))

    nb = params["n_blocks"]
    m = np.ones(nb, bool) if mask is None else np.asarray(mask, bool)
    W = np.vstack([assign(real_key, nb, params["q"])[None], _decoy_assignments(n_decoys, seed, nb, params["q"])])
    A = (W & m).astype(float); B = (~W & m).astype(float)
    na, nb_ = A.sum(1), B.sum(1)
    st = np.where((na > 0) & (nb_ > 0), (A @ losses) / np.maximum(na, 1) - (B @ losses) / np.maximum(nb_, 1), 0.0)
    real, dec = float(st[0]), st[1:]
    return {"stat": real, "decoy_mean": float(dec.mean()), "decoy_std": float(dec.std()),
            "z_vs_decoys": float((real - dec.mean()) / (dec.std() + 1e-12)),
            "p_perm": float((1 + np.sum(dec >= real)) / (1 + n_decoys)), "n_decoys": n_decoys,
            "p_min_possible": 1 / (1 + n_decoys),
            "rel_gap": float(real / max(abs(losses.mean()), 1e-12)) if reference is None else float(real)}


def reference_components(recipe: dict | None) -> list[dict]:
    """The individual reference recipes making up `recipe` (a 'best_of' expands into its parts)."""
    if not recipe:
        return [{"type": "ridge"}]
    if recipe.get("type") == "best_of":
        return [dict(r) for r in recipe["refs"]]
    return [dict(recipe)]


def best_of_test(losses: np.ndarray, params: dict, key: bytes, refs: list[np.ndarray], n_decoys: int = 10000,
                 seed: int = 0, mask: np.ndarray | None = None) -> dict:
    """One holdout test per reference; report the smallest p times the number of references (Bonferroni)."""
    rs = [holdout_test(losses, params, key, n_decoys, seed=seed, reference=r, mask=mask) for r in refs]
    i = int(np.argmin([r["p_perm"] for r in rs]))
    out = dict(rs[i])
    out["p_perm"] = float(min(1.0, rs[i]["p_perm"] * len(rs)))
    out["p_min_possible"] = float(min(1.0, rs[i]["p_min_possible"] * len(rs)))
    out["components"] = [{"p": r["p_perm"], "z": r["z_vs_decoys"]} for r in rs]
    out["best_component"] = i
    return out


def delivered_mask(params: dict, key: bytes) -> np.ndarray:
    return ~assign(key, params["n_blocks"], params["q"])


def reference_losses(original: pd.DataFrame, params: dict, q: dict, recipe: dict | None, seed: int = 0) -> np.ndarray:
    """Per-block losses of the reference model described by `recipe` (None / type 'ridge' -> deterministic ridge).
    A learned reference is trained on windows from ALL blocks (delivered and withheld alike), so it does not depend
    on any licensee's split. Whoever verifies the evidence trains it themselves from the committed recipe."""
    if not recipe or recipe.get("type") == "ridge":
        return ridge_reference(original, params, q)
    from . import models as M
    L, H = q["context"], q["horizon"]
    st, bl, nb = params["start"], params["block_len"], params["n_blocks"]
    X, Y = M.make_windows([original[c].to_numpy(float)[st:st + nb * bl] for c in q["columns"]], L, H,
                          recipe.get("stride", 4))
    f = M.as_forecast(M.train(recipe["arch"], X, Y, L, H, recipe.get("epochs", 5), seed=seed))
    pred = np.concatenate([f(q["ctx"][i:i + 4096]) for i in range(0, len(q["ctx"]), 4096)])
    return losses_from_predictions(q, pred, nb)


def reference_fairness(ref: np.ndarray, params: dict, key: bytes, n_decoys: int = 10000, seed: int = 0) -> dict:
    """Is the reference unusually GOOD on this key's withheld blocks? A reference steered towards the withheld blocks
    (the only way an owner who knows the split could inflate the normalised statistic) shows up here as a small p."""
    lr = np.log(np.maximum(ref, 1e-12))

    def S(k):
        w = assign(k, params["n_blocks"], params["q"])
        return float(lr[w].mean() - lr[~w].mean())
    real = S(key)
    dec = np.array([S(k) for k in decoy_keys_many(n_decoys, seed + 1)])
    return {"stat": real, "z": float((real - dec.mean()) / (dec.std() + 1e-12)),
            "p_fair": float((1 + np.sum(dec <= real)) / (1 + n_decoys))}
